    ('0 0 L * *', datetime(2024, 2, 1), datetime(2024, 2, 29)),
    ('0 0 * * 5L', datetime(2026, 5, 1), datetime(2026, 5, 29)),
    ('0 0 * * 1#2', datetime(2026, 5, 1), datetime(2026, 5, 11)),
    ('0 0 13 * FRI', datetime(2026, 5, 1), datetime(2026, 11, 13)),
    ('0 0 * * 7', datetime(2026, 5, 4), datetime(2026, 5, 10)),
    ('0 0 * * 6-7', datetime(2026, 5, 4), datetime(2026, 5, 9)),
    ('0 0 29 FEB *', datetime(2025, 1, 1), datetime(2028, 2, 29)),
    ('* * * * *', datetime(2026, 5, 4, 10, 0, 30), datetime(2026, 5, 4, 10, 1)),
]
